/** WebSocket links for the shell and tunnel routes; they echo what they receive. */
export const wsHandlers: WebSocketHandler[] = [
  ws.link("*/api/v1/environments/:eid/services/:sid/shell").addEventListener("connection", ({ client }) => {
    client.addEventListener("message", (event) => client.send(event.data));
  }),
  ws.link("*/api/v1/environments/:eid/services/:sid/tunnel").addEventListener("connection", ({ client }) => {
    client.addEventListener("message", (event) => client.send(event.data));
  }),
];
